// Generated by the stp3 Studio Labs build. BepInEx entry for Studio Bridge; the plugin code itself is the same
// as the C# Script Loader script, whose entry is StudioBridgeScript.Main().
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using BepInEx;
using BepInEx.Bootstrap;

[assembly: AssemblyTitle("Studio Bridge")]
[assembly: AssemblyProduct("stp3 Studio Labs")]
[assembly: AssemblyCompany("stp3")]
[assembly: AssemblyVersion("1.1.0.0")]
[assembly: AssemblyFileVersion("1.1.0.0")]

[BepInPlugin(GUID, PluginName, Version)]
[BepInProcess("StudioNEOV2")]
[BepInDependency("marco.kkapi", "1.48")]
[BepInDependency("com.joan6694.illusionplugins.timeline", BepInDependency.DependencyFlags.SoftDependency)]
[BepInDependency("stp3.ragdolllab", BepInDependency.DependencyFlags.SoftDependency)]
[BepInDependency("stp3.wetlab", BepInDependency.DependencyFlags.SoftDependency)]
[BepInDependency("stp3.charatoitem", BepInDependency.DependencyFlags.SoftDependency)]
[BepInDependency("stp3.toolbartweaks", BepInDependency.DependencyFlags.SoftDependency)]
[BepInDependency("horse.coder.tools.scriptloader", BepInDependency.DependencyFlags.SoftDependency)]
public class StudioBridgePlugin : BaseUnityPlugin
{
    public const string GUID = "stp3.studiobridge";
    public const string PluginName = "Studio Bridge";
    public const string Version = "1.1.0";

    // The script copy of this plugin (C# Script Loader, <game>\scripts). With both installed it would run twice.
    static readonly string[] ScriptFiles = { "StudioBridge.cs", "StudioBridgeDof.cs", "StudioBridgeWardrobe.cs" };

    void Awake()
    {
        string copy = ScriptCopy();
        if (copy != null)
        {
            Logger.LogWarning(copy + " (the C# Script Loader copy of " + PluginName + ") is installed, so this DLL stays off. "
                + "Remove one of the two.");
            return;
        }
        StudioBridgeScript.Main();
    }

    static string ScriptCopy()
    {
        if (!Chainloader.PluginInfos.ContainsKey("horse.coder.tools.scriptloader")) return null;
        string dir = Path.Combine(Paths.GameRootPath, "scripts");
        string ignoreFile = Path.Combine(dir, "scriptignores");
        string[] ignored = File.Exists(ignoreFile) ? File.ReadAllLines(ignoreFile).Select(l => l.Trim()).ToArray() : new string[0];
        foreach (string f in ScriptFiles)
            if (File.Exists(Path.Combine(dir, f)) && !ignored.Any(i => string.Equals(i, f, StringComparison.OrdinalIgnoreCase)))
                return "scripts\\" + f;
        return null;
    }
}
